        width: 100%;
        border: 1px solid var(--border);
        border-radius: 14px;
        padding: 14px 16px;
        font: inherit;
        color: inherit;
        background: #fff;
        transition: border-color 160ms ease, box-shadow 160ms ease;
      }

      input::placeholder {
        color: #8a95a6;
      }

      input:focus {
        outline: none;
        border-color: var(--accent);
        box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
