  </head>
  <body>
    <main class="card">
      <p class="eyebrow">Support</p>
      <h1>Contact our team</h1>
      <p class="subtitle">
        Send us a message and we’ll get back to you as soon as possible.
      </p>

      <form id="support-form" novalidate>
        <div class="form-field" data-field="name">
          <label for="full-name">Full name <span class="required">*</span></label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            placeholder="Jane Doe"
            aria-describedby="full-name-error"
          />
          <p class="field-error" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field" data-field="email">
          <label for="email-address">Email address <span class="required">*</span></label>
          <input
            id="email-address"
            name="email"
            type="email"
            autocomplete="email"
            required
            placeholder="jane@example.com"
            aria-describedby="email-address-error"
          />
          <p class="field-error" id="email-address-error" aria-live="polite"></p>
        </div>

        <div class="form-field" data-field="phone">
          <label for="phone-number">Phone number</label>
          <input
            id="phone-number"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            placeholder="+1 (555) 123-4567"
            aria-describedby="phone-number-help phone-number-error"
          />
          <p class="field-help" id="phone-number-help">
            Optional. Use a number like +1 (555) 123-4567.
          </p>
          <p class="field-error" id="phone-number-error" aria-live="polite"></p>
        </div>

        <button type="submit">Submit request</button>
        <p class="status" id="form-status" aria-live="polite"></p>
      </form>
    </main>

    <script>
      const form = document.getElementById("support-form");
      const status = document.getElementById("form-status");

      const fields = {
        name: {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          wrapper: document.querySelector('[data-field="name"]'),
        },
        email: {
          input: document.getElementById("email-address"),
          error: document.getElementById("email-address-error"),
          wrapper: document.querySelector('[data-field="email"]'),
        },
        phone: {
          input: document.getElementById("phone-number"),
          error: document.getElementById("phone-number-error"),
          wrapper: document.querySelector('[data-field="phone"]'),
        },
      };

      const phonePattern = /^\+?[0-9\s().-]{7,}$/;

      function setFieldState(field, message) {
        const isInvalid = Boolean(message);
        field.error.textContent = message;
        field.wrapper.classList.toggle("invalid", isInvalid);
        field.input.setAttribute("aria-invalid", String(isInvalid));
      }

      function validateName() {
        const value = fields.name.input.value.trim();
        if (!value) {
          return "Full name is required.";
        }
        return "";
      }

      function validateEmail() {
        const value = fields.email.input.value.trim();
        if (!value) {
          return "Email address is required.";
        }
        if (!fields.email.input.checkValidity()) {
          return "Enter a valid email address.";
        }
        return "";
      }

      function validatePhone() {
        const value = fields.phone.input.value.trim();
        if (!value) {
          return "";
        }
        if (!phonePattern.test(value)) {
          return "Enter a valid phone number using the expected format.";
        }
        return "";
      }

      function validateField(key) {
        const validators = {
          name: validateName,
          email: validateEmail,
          phone: validatePhone,
        };
        const message = validators[key]();
        setFieldState(fields[key], message);
        return !message;
      }

      function validateForm() {
        const results = ["name", "email", "phone"].map(validateField);
        return results.every(Boolean);
      }

      ["name", "email", "phone"].forEach((key) => {
        fields[key].input.addEventListener("blur", () => validateField(key));
        fields[key].input.addEventListener("input", () => {
          if (fields[key].error.textContent) {
            validateField(key);
          }
          status.textContent = "";
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const isValid = validateForm();

        if (!isValid) {
          status.textContent = "Please fix the highlighted fields and try again.";
          return;
        }

        status.textContent = "Thanks — your request is ready to send.";
        form.reset();
        Object.values(fields).forEach((field) => setFieldState(field, ""));
      });
    </script>
